INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20H9H6K', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $2(5x^2 - 3x) - 3(x^2 + 4x - 9)$?', NULL, $lyceon_json$[{"key":"A","text":"$7x^2 - 18x + 27$"},{"key":"B","text":"$7x^2 - 18x - 27$"},{"key":"C","text":"$13x^2 - 18x + 27$"},{"key":"D","text":"$7x^2 + 6x + 27$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distribute each coefficient: $2(5x^2 - 3x) = 10x^2 - 6x$ and $-3(x^2 + 4x - 9) = -3x^2 - 12x + 27$. Combining like terms gives $10x^2 - 3x^2 = 7x^2$, $-6x - 12x = -18x$, and the constant $27$, so the result is $7x^2 - 18x + 27$. The distractor $7x^2 - 18x - 27$ results from computing $-3(-9)$ as $-27$ instead of $+27$, a sign error on the double negative. The distractor $13x^2 - 18x + 27$ adds the $x^2$ coefficients ($10 + 3 = 13$) instead of subtracting, an arithmetic slip. The distractor $7x^2 + 6x + 27$ incorrectly treats $-3(4x)$ as $+12x$, then combines $-6x + 12x = 6x$, a sign error in the distribution.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20K83YX', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'The expression $\\frac{18x^5 - 12x^3 + 6x^2}{6x^2}$ is equivalent to which of the following?', NULL, $lyceon_json$[{"key":"A","text":"$3x^3 - 2x + 1$"},{"key":"B","text":"$3x^3 - 2x$"},{"key":"C","text":"$12x^3 - 6x + 1$"},{"key":"D","text":"$3x^7 - 2x^5 + x^4$"}]$lyceon_json$::jsonb, 'A', NULL, E'Divide each term by $6x^2$: $\\frac{18x^5}{6x^2} = 3x^3$, $\\frac{-12x^3}{6x^2} = -2x$, $\\frac{6x^2}{6x^2} = 1$. The result is $3x^3 - 2x + 1$. The distractor $3x^3 - 2x$ omits the constant term from dividing $6x^2$ by itself. The distractor $12x^3 - 6x + 1$ subtracts the coefficients instead of dividing them. The distractor $3x^7 - 2x^5 + x^4$ adds exponents instead of subtracting them when dividing.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20WXPR6', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, the measure of angle $P$ is $47°$ and the exterior angle at vertex $R$ measures $119°$. What is the measure, in degrees, of angle $Q$?', NULL, $lyceon_json$[{"key":"A","text":"$14$"},{"key":"B","text":"$61$"},{"key":"C","text":"$72$"},{"key":"D","text":"$108$"}]$lyceon_json$::jsonb, 'C', NULL, E'The exterior angle of a triangle equals the sum of the two non-adjacent interior angles. The exterior angle at $R$ is $119°$, so $\\angle P + \\angle Q = 119°$. Since $\\angle P = 47°$, we have $\\angle Q = 119° - 47° = 72°$. The value $14°$ comes from subtracting both $\\angle P$ and the exterior angle from $180°$ incorrectly ($180 - 119 - 47$). The value $61°$ results from finding the interior angle at $R$ ($180° - 119° = 61°$) and reporting that instead of $\\angle Q$. The value $108°$ arises from adding $\\angle P$ to the interior angle at $R$ ($47 + 61$) as if that were $\\angle Q$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20YDGZW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A store marks up an item by $40\\%$ over its wholesale cost of $\\$63$. During a sale, the store then discounts the marked-up price by $25\\%$. What is the sale price of the item, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"$\\$47.25$"},{"key":"B","text":"$\\$66.15$"},{"key":"C","text":"$\\$72.45$"},{"key":"D","text":"$\\$88.20$"}]$lyceon_json$::jsonb, 'B', NULL, E'The marked-up price is $63 \\times 1.40 = \\$88.20$. The sale price after a $25\\%$ discount is $88.20 \\times 0.75 = \\$66.15$. The value $\\$88.20$ results from computing the markup but not applying the discount. The value $\\$72.45$ comes from subtracting the percentages ($40\\% - 25\\% = 15\\%$) and computing $63 \\times 1.15$, which incorrectly treats successive percentage changes as additive. The value $\\$47.25$ comes from applying the $25\\%$ discount directly to the wholesale cost ($63 \\times 0.75$), bypassing the markup step entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21AB5DE', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'The function $f(x) = 2x^3 - 13x^2 + 17x + 12$ has a zero at $x = 4$. Which of the following expressions is equivalent to $\\frac{f(x)}{x - 4}$?', NULL, $lyceon_json$[{"key":"A","text":"$2x^2 - 5x - 3$"},{"key":"B","text":"$2x^2 - 5x + 3$"},{"key":"C","text":"$2x^2 + 5x - 3$"},{"key":"D","text":"$2x^2 - 13x - 3$"}]$lyceon_json$::jsonb, 'A', NULL, E'Using synthetic division with $x = 4$ on $2x^3 - 13x^2 + 17x + 12$: bring down $2$; $2 \\times 4 = 8$, add to $-13$ to get $-5$; $-5 \\times 4 = -20$, add to $17$ to get $-3$; $-3 \\times 4 = -12$, add to $12$ to get $0$. The quotient is $2x^2 - 5x - 3$. The expression $2x^2 - 5x + 3$ has a sign error on the constant term from mishandling the last addition step. The expression $2x^2 + 5x - 3$ reverses the sign of the $x$ coefficient. The expression $2x^2 - 13x - 3$ uses the original $x^2$ coefficient $-13$ instead of the synthetic division result $-5$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21GJWDI', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What value of $x$ satisfies the equation $3(2x - 7) + 4 = 5x + 9$?', NULL, $lyceon_json$[{"key":"A","text":"$22$"},{"key":"B","text":"$-4$"},{"key":"C","text":"$26$"},{"key":"D","text":"$2$"}]$lyceon_json$::jsonb, 'C', NULL, E'Distributing gives $6x - 21 + 4 = 5x + 9$, which simplifies to $6x - 17 = 5x + 9$. Subtracting $5x$ from both sides gives $x - 17 = 9$, so $x = 26$. The value $22$ comes from an arithmetic slip in the final step, such as computing $9 + 17 = 22$ instead of the correct $9 + 17 = 26$, or from omitting the $+4$ on the left side and solving $6x - 21 = 5x + 9$ to get $x = 30$, then subtracting $8$ somewhere. The value $-4$ arises from a sign error when moving the constant term. The value $2$ results from only partially solving after the distribution step.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22EQ4S4', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'If $\\frac{x^2 - 13x + 42}{x^2 - 11x + 30}$ is rewritten in the form $1 + \\frac{k}{x - 5}$, what is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$-2$"},{"key":"B","text":"$2$"},{"key":"C","text":"$-12$"},{"key":"D","text":"$12$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factor both: $x^2 - 13x + 42 = (x - 6)(x - 7)$ and $x^2 - 11x + 30 = (x - 5)(x - 6)$. After canceling $(x - 6)$, the fraction becomes $\\frac{x - 7}{x - 5}$. Rewrite as $\\frac{(x - 5) - 2}{x - 5} = 1 + \\frac{-2}{x - 5}$, so $k = -2$. The distractor $2$ results from dropping the negative sign. The distractor $-12$ comes from incorrectly using the constant terms of the original polynomials ($42 - 30 = 12$, then negating). The distractor $12$ makes the same arithmetic error without applying the sign.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22JTE17', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'grid_in', E'If $f(x) = x^3 - 2x$, what is $f(3)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '21', ARRAY['21'], E'Substituting $x = 3$: $f(3) = 3^3 - 2(3) = 27 - 6 = 21$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22TPGR3', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'A tutoring center offers two pricing plans. Plan A charges $\\$47$ per session with no other fees. Plan B charges a monthly fee of $\\$189$ plus $\\$23$ per session. What is the minimum number of sessions in a month for which Plan B is strictly less expensive than Plan A?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8', ARRAY['8'], E'Plan A costs $47s$ dollars for $s$ sessions, and Plan B costs $189 + 23s$ dollars. Setting Plan B strictly less than Plan A: $189 + 23s < 47s$. Subtracting $23s$ from both sides gives $189 < 24s$, so $s > 7.875$. Since the number of sessions must be a whole number, the minimum number of sessions for which Plan B is strictly less expensive is 8.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM233WVG3', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'In a right triangle, one leg has length 8 and the angle adjacent to that leg measures $37°$. The length of the other leg is $8 \\tan 37°$. Given that $\\tan 37° \\approx 0.7536$, what is the length of the other leg, rounded to the nearest tenth?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'The other leg equals $8 \\tan 37°$. Using $\\tan 37° \\approx 0.7536$, we get $8 \\times 0.7536 = 6.0288$. Rounded to the nearest tenth, this is $6.0$, which as a grid-in value is $6$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23OJQW3', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'A line passes through the point $(2, -5)$ and is perpendicular to the line $4x - 7y = 28$. What is the $y$-intercept of this line?', NULL, $lyceon_json$[{"key":"A","text":"$-\\dfrac{3}{2}$"},{"key":"B","text":"$\\dfrac{3}{2}$"},{"key":"C","text":"$-\\dfrac{17}{2}$"},{"key":"D","text":"$\\dfrac{7}{4}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewriting $4x - 7y = 28$ in slope-intercept form gives $y = \\frac{4}{7}x - 4$, so the slope is $\\frac{4}{7}$. The perpendicular slope is $-\\frac{7}{4}$. Using point-slope form with $(2, -5)$: $y + 5 = -\\frac{7}{4}(x - 2)$, which gives $y = -\\frac{7}{4}x + \\frac{7}{2} - 5 = -\\frac{7}{4}x - \\frac{3}{2}$. The $y$-intercept is $-\\frac{3}{2}$. The value $\\frac{3}{2}$ results from a sign error on the constant. The value $-\\frac{17}{2}$ comes from an arithmetic slip adding $\\frac{7}{2}$ and $-5$ incorrectly. The value $\\frac{7}{4}$ confuses the perpendicular slope with the $y$-intercept.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM243E9YT', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'grid_in', E'A printer produces 43 pages every 5 minutes. At this rate, how many pages will the printer produce in 35 minutes?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '301', ARRAY['301'], E'The printer produces 43 pages every 5 minutes, so the rate is $\\frac{43}{5}$ pages per minute. In 35 minutes, the printer produces $\\frac{43}{5} \\times 35 = 43 \\times 7 = 301$ pages. A common error is to stop at the rate per minute ($\\frac{43}{5} = 8.6$) without multiplying by the full time. Another error is dividing 35 by 43 instead of multiplying the rate by the time.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24A0J6A', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'The equation $x^2 + bx + 21 = 0$, where $b$ is a constant, has $x = 3$ as one solution. What is the other solution?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$-7$"},{"key":"C","text":"$-3$"},{"key":"D","text":"$21$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 3$: $9 + 3b + 21 = 0$, so $3b = -30$ and $b = -10$. The equation becomes $x^2 - 10x + 21 = 0$, which factors as $(x - 3)(x - 7) = 0$. The other solution is $7$. The value $-7$ results from a sign error in the factored form. The value $-3$ assumes the roots are negatives of each other. The value $21$ confuses the constant term with a root.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25HITJ7', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'What is the solution to the equation $\\dfrac{2x + 5}{3} - \\dfrac{x - 1}{4} = 7$?', NULL, $lyceon_json$[{"key":"A","text":"$\\dfrac{61}{5}$"},{"key":"B","text":"$\\dfrac{64}{5}$"},{"key":"C","text":"$\\dfrac{57}{5}$"},{"key":"D","text":"$\\dfrac{61}{7}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Multiplying every term by 12 (the LCD of 3 and 4) gives $4(2x + 5) - 3(x - 1) = 84$. Expanding: $8x + 20 - 3x + 3 = 84$, so $5x + 23 = 84$. Subtracting 23: $5x = 61$, giving $x = \\frac{61}{5}$. The value $\\frac{64}{5}$ results from dropping the constant when distributing $-3(x - 1)$, computing it as $-3x$ alone and omitting the $+3$. This gives $8x + 20 - 3x = 84$, so $5x + 20 = 84$, yielding $x = \\frac{64}{5}$. The value $\\frac{57}{5}$ comes from computing $8x + 20 - 3x - 3 = 84$ with an arithmetic slip on $20 - 3 = 17$ leading to $5x = 57$. The value $\\frac{61}{7}$ results from multiplying only the first fraction by 4 and the second by 3, then dividing by 7 instead of 5.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27C83YP', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'If $f(x) = 11x - 4$, what is the value of $f(3)$?', NULL, $lyceon_json$[{"key":"A","text":"$29$"},{"key":"B","text":"$37$"},{"key":"C","text":"$33$"},{"key":"D","text":"$-29$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 3$: $f(3) = 11(3) - 4 = 33 - 4 = 29$. The value $37$ results from computing $11(3) + 4$ instead of subtracting $4$. The value $33$ stops at the multiplication step without subtracting $4$. The value $-29$ applies a sign error to the final result.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
