INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28M47XC', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What are all solutions to the equation $(x - 11)(x + 4) = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$x = 11$ or $x = -4$"},{"key":"B","text":"$x = -11$ or $x = 4$"},{"key":"C","text":"$x = 11$ or $x = 4$"},{"key":"D","text":"$x = -11$ or $x = -4$"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting each factor equal to zero gives $x - 11 = 0$ or $x + 4 = 0$, so $x = 11$ or $x = -4$. The pair $x = -11$ or $x = 4$ reverses both signs. The pair $x = 11$ or $x = 4$ applies a sign error to the second factor. The pair $x = -11$ or $x = -4$ negates the first root incorrectly.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29F5REY', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'grid_in', E'The function $f$ is defined by $f(x) = -5x + 37$. For what value of $x$ does $f(x) = 12$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Setting $-5x + 37 = 12$ and subtracting 37 from both sides gives $-5x = -25$. Dividing both sides by $-5$ gives $x = 5$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
