INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AR2PYR', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'A line passes through the points $(1, 11)$ and $(4, 2)$. Which of the following is the equation of this line?', NULL, $lyceon_json$[{"key":"A","text":"$y = -3x + 14$"},{"key":"B","text":"$y = 3x + 8$"},{"key":"C","text":"$y = -3x + 8$"},{"key":"D","text":"$y = -3x - 14$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $\\frac{2 - 11}{4 - 1} = \\frac{-9}{3} = -3$. Using point-slope form with $(1, 11)$: $y - 11 = -3(x - 1)$, so $y = -3x + 3 + 11 = -3x + 14$. The equation $y = 3x + 8$ uses a positive slope of $3$ instead of $-3$, a sign error. The equation $y = -3x + 8$ has the correct slope but an arithmetic slip when computing the $y$-intercept. The equation $y = -3x - 14$ applies a sign error to the constant term.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AY0T9F', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'grid_in', E'If $5(2x - 7) - 3(x + 4)$ is written in the form $ax + b$, what is the value of $b$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-47', ARRAY['-47'], E'Distribute: $5(2x - 7) = 10x - 35$ and $-3(x + 4) = -3x - 12$. Combining gives $(10x - 3x) + (-35 - 12) = 7x - 47$. In the form $ax + b$, the value of $b$ is $-47$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BLW7NW', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'In the $xy$-plane, a circle has center $(2, -5)$ and passes through the point $(11, 7)$. The equation of this circle is $(x - 2)^2 + (y + 5)^2 = r^2$. What is the value of $r^2$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '225', ARRAY['225'], E'To find $r^2$, compute the distance squared from the center $(2, -5)$ to the point $(11, 7)$: $r^2 = (11 - 2)^2 + (7 - (-5))^2 = 9^2 + 12^2 = 81 + 144 = 225$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BN2TO6', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'grid_in', E'The expression $(x + 3)^3 - (x - 3)^3$ can be written as $ax^2 + b$ for constants $a$ and $b$. What is the value of $a + b$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '72', ARRAY['72'], E'Expand using the binomial theorem: $(x + 3)^3 = x^3 + 9x^2 + 27x + 27$ and $(x - 3)^3 = x^3 - 9x^2 + 27x - 27$. Subtracting: $(x^3 + 9x^2 + 27x + 27) - (x^3 - 9x^2 + 27x - 27) = 18x^2 + 54$. The $x^3$ terms and the $27x$ terms cancel, leaving $18x^2 + 54$. Therefore $a = 18$ and $b = 54$, so $a + b = 18 + 54 = 72$.', NULL, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BQBHNV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A scientist models the relationship between the temperature $x$, in degrees Celsius, and the reaction rate $y$, in milligrams per second, with the equation $y = 0.13x + 1.47$. Which of the following is the best interpretation of the slope of this model?', NULL, $lyceon_json$[{"key":"A","text":"For each increase of 1 degree Celsius in temperature, the predicted reaction rate increases by 0.13 milligrams per second."},{"key":"B","text":"For each increase of 1 degree Celsius in temperature, the predicted reaction rate increases by 1.47 milligrams per second."},{"key":"C","text":"At a temperature of 0 degrees Celsius, the predicted reaction rate is 0.13 milligrams per second."},{"key":"D","text":"For each increase of 0.13 degrees Celsius in temperature, the predicted reaction rate increases by 1 milligram per second."}]$lyceon_json$::jsonb, 'A', NULL, E'In the equation $y = 0.13x + 1.47$, the slope is $0.13$, which represents the predicted change in $y$ for each unit increase in $x$. Therefore, for each increase of 1 degree Celsius, the predicted reaction rate increases by $0.13$ milligrams per second. The interpretation stating that the rate increases by $1.47$ milligrams per second confuses the slope with the $y$-intercept. The interpretation stating that $0.13$ is the reaction rate at $0$ degrees Celsius misidentifies the slope as the $y$-intercept value. The interpretation involving an increase of $0.13$ degrees inverts the relationship between the input and output variables.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CCZEW0', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A cone has a radius of 9 inches and a slant height of 41 inches. The height of the cone, in inches, is $h$. What is the volume of the cone, in terms of $\\pi$? (Give the coefficient of $\\pi$ in the volume expression.)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '1080', ARRAY['1080'], E'First find the height using the Pythagorean theorem with the radius and slant height: $h = \\sqrt{41^2 - 9^2} = \\sqrt{1681 - 81} = \\sqrt{1600} = 40$ inches. The volume of a cone is $V = \\frac{1}{3}\\pi r^2 h = \\frac{1}{3}\\pi(9)^2(40) = \\frac{1}{3}\\pi(81)(40) = \\frac{3240}{3}\\pi = 1080\\pi$. The coefficient of $\\pi$ is 1080.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2D5KIJP', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'If $y = x + 3$ and $y = x^2 - 2x - 1$, what is the sum of all $x$-values at the points of intersection?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$4$"},{"key":"C","text":"$-3$"},{"key":"D","text":"$1$"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting $x + 3 = x^2 - 2x - 1$ gives $x^2 - 3x - 4 = 0$. Factoring yields $(x - 4)(x + 1) = 0$, so $x = 4$ or $x = -1$. The sum is $4 + (-1) = 3$. The value $4$ is only one of the two roots, not their sum. The value $-3$ results from a sign error in rearranging the equation. The value $1$ comes from an arithmetic slip, such as computing $4 + (-1)$ as $4 - 1 = 3$ and then subtracting again, or misidentifying one root.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DD8QE4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'Researchers wanted to determine whether a new fertilizer increases tomato yield. They randomly assigned 60 tomato plants to two groups of 30: one group received the new fertilizer, and the other received a standard fertilizer. After 8 weeks, the group receiving the new fertilizer had a significantly higher average yield. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The new fertilizer is associated with, but did not necessarily cause, the higher yield."},{"key":"B","text":"The new fertilizer caused the higher yield in tomato plants."},{"key":"C","text":"The difference in yield is likely due to natural variation among the tomato plants rather than the fertilizer."},{"key":"D","text":"The new fertilizer will increase yield for all types of plants, not just tomato plants."}]$lyceon_json$::jsonb, 'B', NULL, E'Because the researchers used random assignment to divide the plants into two groups, the study is a randomized controlled experiment. Random assignment controls for confounding variables, so a statistically significant difference supports a causal conclusion: the new fertilizer caused the higher yield. The conclusion stating only an association, without causation, would apply to an observational study but not to a properly randomized experiment. The conclusion attributing the difference to natural variation ignores that the result was statistically significant and that random assignment balances natural variation across the groups. The conclusion extending the result to all types of plants goes beyond the scope of the study, which tested only tomato plants.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DXH09B', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A survey of 200 employees found that 84 preferred working remotely, 73 preferred working in the office, and the rest had no preference. Of those who preferred working remotely, 31 were in management positions. If one employee is selected at random from those who preferred remote work, what is the probability that the employee is in a management position?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{31}{200}$"},{"key":"B","text":"$\\frac{31}{84}$"},{"key":"C","text":"$\\frac{84}{200}$"},{"key":"D","text":"$\\frac{31}{43}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The question asks for a conditional probability: given that the employee preferred remote work, what is the probability of being in management? The conditional sample space is the 84 employees who preferred remote work, and 31 of those are in management, so the probability is $\\frac{31}{84}$. The fraction $\\frac{31}{200}$ incorrectly uses the total number of employees as the denominator rather than restricting to the remote-preference group. The fraction $\\frac{84}{200}$ gives the probability of preferring remote work rather than the probability of being in management given remote preference. The fraction $\\frac{31}{43}$ uses an incorrect denominator of 43 (the number with no preference: $200 - 84 - 73 = 43$), confusing the subgroups.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EJWGGN', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A farmer has at most 200 acres available for planting wheat and corn. Wheat requires 3 workers per acre and corn requires 5 workers per acre, and the farmer can hire at most 760 workers. If the farmer must plant at least 50 acres of wheat, what is the maximum number of acres of corn the farmer can plant?', NULL, $lyceon_json$[{"key":"A","text":"100"},{"key":"B","text":"150"},{"key":"C","text":"122"},{"key":"D","text":"130"}]$lyceon_json$::jsonb, 'C', NULL, E'Let $w$ be acres of wheat and $c$ be acres of corn. The constraints are $w + c \\leq 200$, $3w + 5c \\leq 760$, and $w \\geq 50$. To maximize $c$, set $w$ to its minimum value of 50. From the acreage constraint: $50 + c \\leq 200$, so $c \\leq 150$. From the worker constraint: $3(50) + 5c \\leq 760$, giving $150 + 5c \\leq 760$, so $5c \\leq 610$ and $c \\leq 122$. The binding constraint is $c \\leq 122$, so the maximum is 122. The distractor 150 considers only the acreage constraint and ignores the worker constraint. The distractor 130 results from an arithmetic error when solving $5c \\leq 610$. The distractor 100 results from using an incorrect worker-per-acre ratio.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F6WWS8', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which of the following is the solution to the inequality $4x + 11 \\leq 39$?', NULL, $lyceon_json$[{"key":"A","text":"$x \\leq 7$"},{"key":"B","text":"$x \\leq 28$"},{"key":"C","text":"$x \\geq 7$"},{"key":"D","text":"$x \\leq 10$"}]$lyceon_json$::jsonb, 'A', NULL, E'Subtracting 11 from both sides gives $4x \\leq 28$, and dividing both sides by 4 gives $x \\leq 7$. The distractor $x \\leq 28$ results from forgetting to divide by 4 after subtracting 11. The distractor $x \\geq 7$ incorrectly reverses the inequality direction when dividing by a positive number. The distractor $x \\leq 10$ comes from adding 11 to 39 instead of subtracting, then dividing by an incorrect factor.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F77VM1', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $3x + 7y = 21$?', NULL, $lyceon_json$[{"key":"A","text":"$(0, 7)$"},{"key":"B","text":"$(0, 3)$"},{"key":"C","text":"$(7, 0)$"},{"key":"D","text":"$(0, 21)$"}]$lyceon_json$::jsonb, 'B', NULL, E'The $y$-intercept occurs when $x = 0$. Substituting gives $7y = 21$, so $y = 3$, and the $y$-intercept is $(0, 3)$. The point $(0, 7)$ incorrectly uses the coefficient of $y$ as the intercept value. The point $(7, 0)$ is the $x$-intercept, not the $y$-intercept. The point $(0, 21)$ uses the constant on the right side without dividing by the coefficient of $y$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GED49C', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $4x^2 - 49$?', NULL, $lyceon_json$[{"key":"A","text":"$(4x - 7)(x + 7)$"},{"key":"B","text":"$(2x + 7)(2x - 7)$"},{"key":"C","text":"$(2x - 7)^2$"},{"key":"D","text":"$(2x + 49)(2x - 1)$"}]$lyceon_json$::jsonb, 'B', NULL, E'The expression $4x^2 - 49$ is a difference of squares: $(2x)^2 - 7^2 = (2x + 7)(2x - 7)$. The distractor $(4x - 7)(x + 7)$ incorrectly splits $4x^2$ as $4x \\cdot x$ instead of recognizing the perfect square structure, and expanding it gives $4x^2 + 21x - 49$, which has an extra middle term. The distractor $(2x - 7)^2$ expands to $4x^2 - 28x + 49$, which includes both a middle term and a positive constant. The distractor $(2x + 49)(2x - 1)$ expands to $4x^2 + 96x - 49$, a fundamentally different expression.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GTNB4Y', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A paint mixture requires 7 parts blue paint to 3 parts white paint by volume. Blue paint costs $\\$13$ per liter and white paint costs $\\$5$ per liter. What is the total cost, in dollars, of the paint needed to make 4 liters of this mixture?', NULL, $lyceon_json$[{"key":"A","text":"$\\$36.00$"},{"key":"B","text":"$\\$36.40$"},{"key":"C","text":"$\\$42.40$"},{"key":"D","text":"$\\$52.00$"}]$lyceon_json$::jsonb, 'C', NULL, E'In the 7:3 ratio, the total parts are $7 + 3 = 10$. For 4 liters, the blue paint volume is $\\frac{7}{10} \\times 4 = 2.8$ liters and the white paint volume is $\\frac{3}{10} \\times 4 = 1.2$ liters. The blue paint cost is $2.8 \\times 13 = \\$36.40$ and the white paint cost is $1.2 \\times 5 = \\$6.00$, giving a total of $\\$42.40$. The value $\\$36.40$ results from computing only the blue paint cost and omitting the white paint. The value $\\$36.00$ comes from incorrectly splitting the 4 liters equally (2 liters each), giving $2 \\times 13 + 2 \\times 5 = 36$. The value $\\$52.00$ results from multiplying the full 4 liters by the blue paint price alone ($4 \\times 13$), ignoring the ratio entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H0MDOU', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'The equation $9x - 4y = 36$ represents a line. What is the $x$-coordinate of the point on this line where $y = 9$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8', ARRAY['8'], E'Substituting $y = 9$ into $9x - 4(9) = 36$ gives $9x - 36 = 36$. Adding 36 to both sides: $9x = 72$. Dividing by 9: $x = 8$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I3G9NH', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'Which of the following ordered pairs $(x, y)$ is a solution to the inequality $3x - 5y < -17$?', NULL, $lyceon_json$[{"key":"A","text":"$(2, 3)$"},{"key":"B","text":"$(-1, 4)$"},{"key":"C","text":"$(0, 3)$"},{"key":"D","text":"$(-2, 1)$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $(-1, 4)$: $3(-1) - 5(4) = -3 - 20 = -23$, and $-23 < -17$ is true, so $(-1, 4)$ is a solution. For $(2, 3)$: $3(2) - 5(3) = 6 - 15 = -9$, and $-9 < -17$ is false. For $(0, 3)$: $3(0) - 5(3) = -15$, and $-15 < -17$ is false. For $(-2, 1)$: $3(-2) - 5(1) = -6 - 5 = -11$, and $-11 < -17$ is false.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I8H1TG', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'If $4(x + 3) - 2x = 3x - 1$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '13', ARRAY['13'], E'Distributing gives $4x + 12 - 2x = 3x - 1$, which simplifies to $2x + 12 = 3x - 1$. Subtracting $2x$ from both sides gives $12 = x - 1$, and adding 1 to both sides gives $x = 13$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IKNW39', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'The function $f$ is linear. If $f(2) = 17$ and $f(9) = -11$, what is the value of $f(0)$?', NULL, $lyceon_json$[{"key":"A","text":"$21$"},{"key":"B","text":"$25$"},{"key":"C","text":"$9$"},{"key":"D","text":"$-25$"}]$lyceon_json$::jsonb, 'B', NULL, E'The slope is $\\frac{-11 - 17}{9 - 2} = \\frac{-28}{7} = -4$. Using $f(2) = 17$: $17 = -4(2) + b$, so $b = 25$. Therefore $f(0) = 25$. The value $21$ arises from an arithmetic slip such as computing $17 + 4 = 21$ instead of $17 + 8 = 25$. The value $9$ results from partial reasoning, such as computing the slope but substituting incorrectly. The value $-25$ comes from a sign error on the $y$-intercept.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LCUDFQ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'If $\\frac{x^2 - 9}{x - 3} = 2x + 7$ and $x \\neq 3$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-4', ARRAY['-4'], E'Since $x \\neq 3$, we can factor the numerator: $\\frac{(x - 3)(x + 3)}{x - 3} = x + 3$. Setting $x + 3 = 2x + 7$ and solving: $3 - 7 = 2x - x$, so $x = -4$. Checking: $x + 3 = -4 + 3 = -1$ and $2(-4) + 7 = -1$, confirming the solution.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LLG6FJ', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A gym charges a one-time registration fee of $\\$47$ and a monthly membership fee of $\\$19$. Which function $f$ gives the total cost, in dollars, after $m$ months, and what is $f(7)$?', NULL, $lyceon_json$[{"key":"A","text":"$f(m) = 47m + 19$; $f(7) = 348$"},{"key":"B","text":"$f(m) = 19m + 47$; $f(7) = 180$"},{"key":"C","text":"$f(m) = 19m + 47$; $f(7) = 133$"},{"key":"D","text":"$f(m) = 19m - 47$; $f(7) = 86$"}]$lyceon_json$::jsonb, 'B', NULL, E'The total cost is the monthly fee times the number of months plus the one-time fee: $f(m) = 19m + 47$. Evaluating at $m = 7$: $f(7) = 19(7) + 47 = 133 + 47 = 180$. The option giving $f(m) = 47m + 19$ reverses the roles of the registration fee and the monthly fee. The option showing $f(7) = 133$ uses the correct function but omits the registration fee in the evaluation. The option with $f(m) = 19m - 47$ applies a sign error to the registration fee.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MO25Z7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'grid_in', E'A data set contains the values 11, 14, 19, 23, and 37. What is the median of this data set?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '19', ARRAY['19'], E'When the values are listed in order (11, 14, 19, 23, 37), the median is the middle value. Since there are 5 values, the median is the third value, which is $19$. A common error is computing the mean instead of the median, which would give $\\frac{11 + 14 + 19 + 23 + 37}{5} = \\frac{104}{5} = 20.8$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NQ9Y8Z', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle in the $xy$-plane has the equation $(x + 7)^2 + (y - 3)^2 = 169$. What is the length of the diameter of this circle?', NULL, $lyceon_json$[{"key":"A","text":"$13$"},{"key":"B","text":"$26$"},{"key":"C","text":"$169$"},{"key":"D","text":"$338$"}]$lyceon_json$::jsonb, 'B', NULL, E'The standard form $(x - h)^2 + (y - k)^2 = r^2$ gives $r^2 = 169$, so the radius is $r = 13$. The diameter is $2r = 2(13) = 26$. The value $13$ is the radius, not the diameter -- a common error of stopping one step early. The value $169$ is $r^2$, not the diameter. The value $338$ results from doubling $r^2 = 169$ to get $2 \\times 169 = 338$, confusing the diameter formula $2r$ with $2r^2$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O4YNF6', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A cylinder has a radius of 5 centimeters and a height of 11 centimeters. What is the volume, in cubic centimeters, of the cylinder?', NULL, $lyceon_json$[{"key":"A","text":"$275\\pi$"},{"key":"B","text":"$110\\pi$"},{"key":"C","text":"$55\\pi$"},{"key":"D","text":"$550\\pi$"}]$lyceon_json$::jsonb, 'A', NULL, E'The volume of a cylinder is $V = \\pi r^2 h$. Substituting $r = 5$ and $h = 11$ gives $V = \\pi(5)^2(11) = \\pi(25)(11) = 275\\pi$ cubic centimeters. The value $110\\pi$ results from using $2rh$ instead of $r^2 h$, confusing the volume formula with a lateral surface area component. The value $55\\pi$ comes from using $rh$ without squaring the radius. The value $550\\pi$ arises from doubling the correct result, perhaps confusing with a formula for two cylinders or misapplying a factor.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
