INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OW4TXQ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'If $7x^2 = 252$, what is the positive value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'Dividing both sides by $7$ gives $x^2 = 36$. Taking the square root yields $x = 6$ or $x = -6$. The positive value is $6$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P5WQHF', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $7x^2 - 3x + 4x^2 + 9x$?', NULL, $lyceon_json$[{"key":"A","text":"$11x^2 + 6x$"},{"key":"B","text":"$11x^2 - 6x$"},{"key":"C","text":"$3x^2 + 6x$"},{"key":"D","text":"$11x^2 + 12x$"}]$lyceon_json$::jsonb, 'A', NULL, E'Combining like terms: $7x^2 + 4x^2 = 11x^2$ and $-3x + 9x = 6x$, so the expression simplifies to $11x^2 + 6x$. The distractor $11x^2 - 6x$ results from subtracting $9x - 3x$ with the wrong sign. The distractor $3x^2 + 6x$ comes from subtracting the $x^2$ terms instead of adding them. The distractor $11x^2 + 12x$ comes from adding the absolute values of the $x$ coefficients ($3 + 9 = 12$) instead of using the signed values.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QIKKBD', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A random sample of 400 residents in a city found that $58\\%$ supported a proposed park renovation, with a margin of error of 4 percentage points at $95\\%$ confidence. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $58\\%$ of all residents in the city support the proposed park renovation."},{"key":"B","text":"It is plausible that between $54\\%$ and $62\\%$ of all residents in the city support the proposed park renovation."},{"key":"C","text":"Exactly $54\\%$ of all residents in the city support the proposed park renovation."},{"key":"D","text":"At least $62\\%$ of all residents in the city support the proposed park renovation."}]$lyceon_json$::jsonb, 'B', NULL, E'The margin of error of 4 percentage points means the confidence interval is $58\\% \\pm 4\\%$, or from $54\\%$ to $62\\%$. This interval estimates the true population proportion, so it is plausible that between $54\\%$ and $62\\%$ of all residents support the renovation. The conclusion stating exactly $58\\%$ treats the sample statistic as the exact population parameter, ignoring sampling variability. The conclusion stating exactly 54% treats the lower bound of the confidence interval as the exact population parameter, ignoring that the interval expresses a range of plausible values rather than a single precise figure. The conclusion stating at least $62\\%$ uses only the upper bound of the interval and overstates the finding.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QXKIVN', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'What is the positive value of $x$ if $\\sqrt{5x + 11} = x + 1$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Squaring both sides: $5x + 11 = (x + 1)^2 = x^2 + 2x + 1$. Rearranging: $x^2 - 3x - 10 = 0$. Factoring: $(x - 5)(x + 2) = 0$, giving $x = 5$ or $x = -2$. Checking $x = 5$: $\\sqrt{5(5) + 11} = \\sqrt{36} = 6$ and $5 + 1 = 6$, which confirms the solution. Checking $x = -2$: $\\sqrt{5(-2) + 11} = \\sqrt{1} = 1$ and $-2 + 1 = -1$, so $x = -2$ is extraneous. The answer is $5$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RHYCT6', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What is the value of $x$ if $\\frac{x}{3} + 8 = 15$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$21$"},{"key":"C","text":"$69$"},{"key":"D","text":"$-21$"}]$lyceon_json$::jsonb, 'B', NULL, E'Subtracting 8 from both sides gives $\\frac{x}{3} = 7$. Multiplying both sides by 3 gives $x = 21$. The value $7$ results from stopping after the subtraction step and reporting $\\frac{x}{3} = 7$ as the answer, incomplete reasoning. The value $69$ comes from multiplying 15 by 3 and then adding 8 times 3, an equation setup error ($15 \\times 3 + 8 \\times 3 = 69$). The value $-21$ applies a sign error when multiplying both sides by 3.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SVFR6M', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $h(x) = -2(x - 4)^2 + 13$ models the height of a projectile. What is the maximum value of $h(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$13$"},{"key":"C","text":"$-2$"},{"key":"D","text":"$-13$"}]$lyceon_json$::jsonb, 'B', NULL, E'The function is in vertex form $a(x - h)^2 + k$ with $a = -2$, $h = 4$, $k = 13$. Since $a < 0$, the parabola opens downward, and the maximum output value is $k = 13$. The value $4$ is the $x$-coordinate of the vertex, not the maximum output. The value $-2$ is the leading coefficient and not a function value. The value $-13$ results from negating the correct maximum.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SXJND5', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'A function $g$ is defined by $g(x) = a \\cdot b^x$, where $a$ and $b$ are positive constants. If $g(2) = 54$ and $g(5) = 1458$, what is the value of $g(0)$?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$3$"},{"key":"C","text":"$18$"},{"key":"D","text":"$2$"}]$lyceon_json$::jsonb, 'A', NULL, E'Dividing $g(5)$ by $g(2)$ gives $\\frac{a \\cdot b^5}{a \\cdot b^2} = b^3 = \\frac{1458}{54} = 27$, so $b = 3$. Substituting back into $g(2) = a \\cdot 3^2 = 9a = 54$ gives $a = 6$. Since $g(0) = a \\cdot b^0 = a = 6$, the answer is $6$. The value $3$ is the base $b$, not the value of $g(0)$. The value $18$ results from dividing $54$ by $3$ instead of by $9$. The value $2$ results from incorrectly computing $a$ as $\\frac{54}{27}$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TCWX9T', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'For what value of $k$ does the system $y = x^2 - 5x + k$ and $y = x - 3$ have exactly one solution?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$-6$"},{"key":"C","text":"$3$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting $x^2 - 5x + k = x - 3$ gives $x^2 - 6x + (k + 3) = 0$. For exactly one solution, the discriminant must equal zero: $(-6)^2 - 4(1)(k + 3) = 0$. This gives $36 - 4k - 12 = 0$, so $24 = 4k$ and $k = 6$. The value $-6$ results from a sign error when isolating $k$. The value $3$ comes from dividing $12$ by $4$ instead of $24$ by $4$. The value $9$ comes from setting $36 - 4k = 0$ and ignoring the constant term $-12$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UTQ7RE', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The exponential function $p(t) = 850 \\cdot (1.06)^t$ models a population after $t$ years. By what percent does the population increase each year?', NULL, $lyceon_json$[{"key":"A","text":"$0.6\\%$"},{"key":"B","text":"$1.06\\%$"},{"key":"C","text":"$6\\%$"},{"key":"D","text":"$60\\%$"}]$lyceon_json$::jsonb, 'C', NULL, E'In the model $p(t) = 850 \\cdot (1.06)^t$, the base $1.06$ equals $1 + 0.06$, representing a $6\\%$ annual increase. The value $0.6\\%$ incorrectly reads $0.06$ as $0.006$. The value $1.06\\%$ mistakes the entire growth factor for the percentage. The value $60\\%$ incorrectly shifts the decimal point in $0.06$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"unit_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V4FU4C', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangular garden has a length of 13 feet and a width of 7 feet. What is the area, in square feet, of the garden?', NULL, $lyceon_json$[{"key":"A","text":"40"},{"key":"B","text":"91"},{"key":"C","text":"84"},{"key":"D","text":"20"}]$lyceon_json$::jsonb, 'B', NULL, E'The area of a rectangle is length times width: $13 \\times 7 = 91$ square feet. The value 40 results from calculating the perimeter, $2(13 + 7) = 40$, instead of the area. The answer 84 results from using $12 \\times 7$, an arithmetic error. The answer 20 results from simply adding the two dimensions.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V4R0JM', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'If $f(x) = 2^x$ and $f(a) = 32$, what is the value of $a$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'We need $2^a = 32$. Since $2^5 = 32$, the value of $a$ is $5$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V7R3V1', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In a right triangle, the side opposite angle $\\theta$ has length 21 and the hypotenuse has length 29. What is the value of $\\cos \\theta$?', NULL, $lyceon_json$[{"key":"A","text":"$\\dfrac{20}{29}$"},{"key":"B","text":"$\\dfrac{21}{29}$"},{"key":"C","text":"$\\dfrac{21}{20}$"},{"key":"D","text":"$\\dfrac{29}{21}$"}]$lyceon_json$::jsonb, 'A', NULL, E'First find the adjacent side using the Pythagorean theorem: $a = \\sqrt{29^2 - 21^2} = \\sqrt{841 - 441} = \\sqrt{400} = 20$. Cosine is adjacent over hypotenuse: $\\cos \\theta = \\frac{20}{29}$. The value $\\frac{21}{29}$ uses the opposite side over hypotenuse, which is $\\sin \\theta$, not $\\cos \\theta$. The value $\\frac{21}{20}$ is opposite over adjacent, which is $\\tan \\theta$. The value $\\frac{29}{21}$ is hypotenuse over opposite, which is $\\csc \\theta$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W64XVB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'The ages, in years, of 7 participants in a workshop are 19, 24, 31, 31, 35, 38, and 83. If the participant who is 83 years old leaves the workshop, which of the following best describes the change in the mean and the median of the remaining ages?', NULL, $lyceon_json$[{"key":"A","text":"The mean decreases and the median stays the same."},{"key":"B","text":"The mean decreases and the median decreases."},{"key":"C","text":"The mean stays the same and the median decreases."},{"key":"D","text":"Both the mean and the median stay the same."}]$lyceon_json$::jsonb, 'A', NULL, E'With all 7 values, the mean is $\\frac{19 + 24 + 31 + 31 + 35 + 38 + 83}{7} = \\frac{261}{7} \\approx 37.3$ and the median (the 4th value) is $31$. After removing 83, the 6 remaining values are 19, 24, 31, 31, 35, 38, so the mean is $\\frac{178}{6} \\approx 29.7$ (a decrease) and the median is $\\frac{31 + 31}{2} = 31$ (unchanged). The mean decreases because the removed value (83) is much larger than the original mean, pulling the average down. The median stays at 31 because both middle values of the remaining set are 31. The conclusion that the median also decreases incorrectly assumes that removing any value changes the median. The conclusion that the mean stays the same ignores the effect of removing a high outlier.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WAQD9P', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'If $h(x) = 5 - x^3$, what is the value of $h(-3)$?', NULL, $lyceon_json$[{"key":"A","text":"$32$"},{"key":"B","text":"$-22$"},{"key":"C","text":"$22$"},{"key":"D","text":"$-32$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = -3$: $h(-3) = 5 - (-3)^3 = 5 - (-27) = 5 + 27 = 32$. The value $-22$ results from incorrectly computing $(-3)^3$ as $27$ instead of $-27$, giving $5 - 27 = -22$. The value $22$ comes from computing $(-3)^3$ as $27$ and then subtracting $5$ from $27$. The value $-32$ results from negating the entire expression.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WCU5L6', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'grid_in', E'A store charges $\\$13$ per item plus a flat $\\$29$ shipping fee per order. A customer has at most $\\$250$ to spend on a single order. What is the maximum number of whole items the customer can order?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '17', ARRAY['17'], E'The total cost is $13n + 29$, where $n$ is the number of items. The constraint is $13n + 29 \\leq 250$. Subtracting 29 from both sides gives $13n \\leq 221$. Dividing both sides by 13 gives $n \\leq 17$. Since $n$ must be a whole number, the maximum is 17.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XQ428I', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two parallel lines are cut by a transversal. One of the angles formed measures $53°$. What is the measure, in degrees, of the same-side interior angle that is supplementary to it?', NULL, $lyceon_json$[{"key":"A","text":"$37$"},{"key":"B","text":"$53$"},{"key":"C","text":"$127$"},{"key":"D","text":"$143$"}]$lyceon_json$::jsonb, 'C', NULL, E'Same-side interior angles (also called co-interior or consecutive interior angles) formed by parallel lines and a transversal are supplementary, meaning they add to $180°$. Therefore the angle is $180° - 53° = 127°$. The value $37°$ results from subtracting from $90°$ instead of $180°$, confusing supplementary with complementary. The value $53°$ would be the alternate interior angle, not the same-side interior angle. The value $143°$ results from subtracting from $180°$ but using $37°$ instead of $53°$, a double error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW201SH5V', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The architect Yuki Tanabe designed a library whose cantilevered reading rooms extend over a ravine in central ________ suspended above the treetops, the rooms offer panoramic views while shielding readers from the intense afternoon sun.', $lyceon_json$[{"key":"A","text":"Oregon;"},{"key":"B","text":"Oregon,"},{"key":"C","text":"Oregon"},{"key":"D","text":"Oregon, and"}]$lyceon_json$::jsonb, 'A', NULL, E'The text contains two independent clauses: ''The architect Yuki Tanabe designed a library whose cantilevered reading rooms extend over a ravine in central Oregon'' and ''suspended above the treetops, the rooms offer panoramic views while shielding readers from the intense afternoon sun.'' A semicolon correctly joins these two independent clauses. A comma (''Oregon,'') creates a comma splice between the independent clauses. Omitting punctuation entirely (''Oregon'') produces a fused run-on sentence. Adding ''and'' after the comma (''Oregon, and'') is incorrect because the second clause, beginning with the participial phrase ''suspended above the treetops,'' is an independent clause with its own subject (''the rooms''), and the coordinating conjunction ''and'' joined to the comma creates a grammatically awkward construction that treats the participial phrase as if it were coordinating two main clauses when in fact the two clauses have distinct subjects and the participial phrase modifies only the second.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23B59A9', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes a difference in how the authors of the two texts approach the topic of sleep and memory?', E'Text 1: Neuroscientist Giulio Tononi has proposed that the primary function of sleep is synaptic downscaling: during waking hours, synaptic connections throughout the brain grow stronger as a person learns and processes information, and sleep serves to proportionally weaken these connections back to a sustainable baseline. This renormalization prevents the brain from becoming saturated and allows it to learn efficiently the next day. Under this model, memory consolidation during sleep is a byproduct of downscaling, not a dedicated process.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24AXEI1', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Geothermal energy harnesses heat from beneath Earth''s surface to generate electricity. Unlike solar and wind power, geothermal plants can operate continuously regardless of weather conditions. ________ geothermal energy currently accounts for less than 1% of global electricity production, largely because suitable geological sites are geographically limited.', $lyceon_json$[{"key":"A","text":"For instance,"},{"key":"B","text":"Nevertheless,"},{"key":"C","text":"Similarly,"},{"key":"D","text":"In other words,"}]$lyceon_json$::jsonb, 'B', NULL, E'The preceding sentence highlights a strength of geothermal energy (continuous operation), while the sentence after the blank introduces a contrasting limitation (less than 1% of global production). A contrast transition is needed. ''Nevertheless'' correctly signals that the following statement runs counter to what the previous sentence might lead one to expect. ''For instance'' would introduce an example of the preceding claim rather than a contrast. ''Similarly'' would signal agreement or parallel information, which conflicts with the shift from an advantage to a limitation. ''In other words'' would signal a restatement of the same idea, but the sentence after the blank introduces new, contrasting information.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24CQLVQ', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best states the main idea of the text?', E'In a 2023 paper published in the Journal of Cognitive Neuroscience, psychologist Mariana Soledad Vidal and her colleagues examined how bilingual individuals process idiomatic expressions in their second language. The researchers presented forty-three Spanish-English bilinguals with English idioms embedded in sentence contexts and measured their neural responses using magnetoencephalography. Vidal''s team found that participants who had acquired English before age seven processed idioms similarly to monolingual English speakers, activating regions associated with figurative language comprehension. However, participants who learned English after age twelve showed heightened activation in areas linked to literal semantic analysis, suggesting they were decomposing idioms word by word rather than retrieving them as unified expressions.', $lyceon_json$[{"key":"A","text":"Bilingual individuals who learned a second language early in life process idioms in that language differently from those who acquired it later, according to research by Vidal and colleagues."},{"key":"B","text":"Magnetoencephalography is a more effective tool than other neuroimaging methods for studying how bilingual speakers comprehend figurative language in controlled laboratory settings."},{"key":"C","text":"Spanish-English bilinguals universally struggle to understand English idiomatic expressions because the figurative meanings cannot be directly translated between the two languages."},{"key":"D","text":"Vidal's research demonstrates that monolingual English speakers activate a broader range of neural regions when processing idiomatic expressions than bilingual speakers do regardless of acquisition age."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice about early versus late second-language learners processing idioms differently. The passage centrally contrasts two groups of bilinguals: those who acquired English before age seven, who process idioms like monolinguals, and those who learned after age twelve, who decompose idioms literally. The choice about magnetoencephalography being more effective than other methods misreads the passage, which uses magnetoencephalography as a tool but never compares it to alternatives. The choice claiming bilinguals universally struggle with idioms overstates the findings; the passage shows that early learners process idioms similarly to monolinguals. The choice about monolinguals activating broader neural regions reverses the passage''s point; the passage discusses bilingual participants'' neural patterns, not an expanded range in monolinguals.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW277FIWI', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding, if true, would most directly undermine the claim made by Petrov and colleagues?', E'In a 2024 study, environmental chemist Aleksei Petrov and colleagues proposed that the elevated mercury concentrations observed in lake sediments across central Siberia over the past fifty years result primarily from atmospheric deposition of mercury released by coal-fired power plants in the region. They noted that the timing of the mercury increase corresponds with a period of rapid industrialization in central Siberia. However, geologist Yuna Takahashi has pointed out that the same fifty-year period also coincides with accelerated permafrost thaw across the region, which could release naturally sequestered mercury from previously frozen soils into waterways that feed the lakes.', $lyceon_json$[{"key":"A","text":"Sediment cores from lakes located downwind of coal-fired power plants show mercury concentration profiles nearly identical to those from lakes situated far from any industrial facilities but in areas experiencing significant permafrost degradation."},{"key":"B","text":"Mercury emissions from coal-fired power plants in central Siberia have increased steadily over the past fifty years, closely tracking the region's growth in electricity generation capacity during that same period."},{"key":"C","text":"Lakes in central Siberia that are fed by rivers originating in permafrost zones contain higher concentrations of dissolved organic carbon than lakes fed by rivers flowing through regions without permafrost."},{"key":"D","text":"Atmospheric mercury monitoring stations positioned near coal-fired power plants in central Siberia consistently detect mercury concentrations above the global background average for comparable atmospheric monitoring stations positioned in non-industrial regions worldwide."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the finding about lakes downwind of power plants showing mercury profiles identical to those from lakes near permafrost degradation but far from industry. If proximity to coal plants does not produce distinctly higher mercury concentrations compared to areas with permafrost thaw alone, the atmospheric deposition explanation is undermined because the mercury pattern does not track with industrial proximity. The finding about steadily increasing mercury emissions from power plants would support rather than undermine Petrov''s claim, since it would corroborate the link between industrial activity and mercury deposition. The finding about dissolved organic carbon in permafrost-fed lakes addresses water chemistry rather than mercury concentrations specifically, providing only indirect relevance to the competing explanations without directly undermining the atmospheric deposition claim. The finding about monitoring stations near power plants detecting elevated atmospheric mercury would support Petrov''s claim by confirming that power plants release mercury into the atmosphere, which is precisely the mechanism his hypothesis proposes.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BEIWQR', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1: Ecologist James Whitfield has argued that urban green spaces, such as parks and community gardens, serve primarily as recreational amenities for city residents. In his view, their ecological value is negligible because they are too small and fragmented to sustain viable populations of native species.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2C4496W', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The novelist Priya Subramaniam, who published her first collection of short stories at age nineteen, ________ on a memoir that chronicles her family''s journey from Chennai to Vancouver during the 1990s.', $lyceon_json$[{"key":"A","text":"is currently working"},{"key":"B","text":"are currently working"},{"key":"C","text":"currently working"},{"key":"D","text":"have currently been working"}]$lyceon_json$::jsonb, 'A', NULL, E'The subject is ''The novelist Priya Subramaniam,'' which is singular. The intervening nonrestrictive clause (''who published her first collection of short stories at age nineteen'') does not change the number of the subject. The singular present progressive ''is currently working'' correctly agrees with the singular subject and conveys an ongoing action. ''Are currently working'' uses a plural auxiliary that does not match the singular subject. ''Currently working'' omits the auxiliary verb entirely, producing a sentence fragment instead of a complete predicate. ''Have currently been working'' uses a plural auxiliary, violating agreement with the singular subject.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2C99UDP', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Entomologist Kenji Watanabe studied the pollination patterns of wild buckwheat in three alpine meadows in Hokkaido, Japan. He observed that bumblebees visited buckwheat flowers most frequently during the early morning hours, when nectar production peaks. In the afternoon, when nectar levels declined, bumblebees largely abandoned the buckwheat in favor of nearby gentian plants. Watanabe noted that the buckwheat flowers'' brief nectar window coincided precisely with the period when bumblebee colonies were most actively provisioning larvae. Based on these observations, Watanabe concluded that ________', $lyceon_json$[{"key":"A","text":"the timing of buckwheat nectar production has likely been shaped by selective pressure to coincide with peak bumblebee foraging activity."},{"key":"B","text":"bumblebee colonies in alpine meadows depend entirely on buckwheat nectar and could not survive if buckwheat populations declined significantly."},{"key":"C","text":"gentian plants produce substantially more nectar than buckwheat plants across all hours of the day in these alpine environments."},{"key":"D","text":"the pollination patterns of wild buckwheat are identical across all alpine meadow ecosystems regardless of geographic location or pollinator availability."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice about selective pressure shaping buckwheat nectar timing to coincide with peak bumblebee foraging. The passage establishes that nectar production peaks when bumblebees are most actively foraging, suggesting a co-evolved relationship. The choice claiming bumblebees depend entirely on buckwheat overstates the evidence, since the passage shows bumblebees also visit gentian plants. The choice about gentian producing more nectar across all hours goes beyond what the passage states; bumblebees shift to gentian in the afternoon, but the passage does not compare total nectar output. The choice about identical pollination patterns across all alpine ecosystems makes a sweeping generalization unsupported by a study of only three meadows in one region.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2D5EONF', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'The student wants to emphasize the influence of ukiyo-e on Western art. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'While researching the history of printmaking, a student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DDNT79', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'In 1847, the Hungarian physician Ignaz Semmelweis observed that the mortality rate among mothers in a Vienna maternity ward staffed by medical students was nearly five times higher than in a ward staffed by midwives. He hypothesized that students were transferring infectious material from autopsies to patients. After instituting a policy requiring hand-washing with chlorinated lime, mortality in the students'' ward plummeted from 18 percent to under 2 percent. Despite this dramatic evidence, Semmelweis''s colleagues largely rejected his findings, and widespread adoption of antiseptic practices did not occur until decades later.', $lyceon_json$[{"key":"A","text":"It presents a historical observation, describes the intervention that resulted from it, and then notes the surprising resistance to the findings."},{"key":"B","text":"It compares two competing scientific theories and evaluates which theory was ultimately vindicated by later experiments."},{"key":"C","text":"It narrates a personal tragedy and reflects on its lasting emotional impact on the medical profession."},{"key":"D","text":"It introduces a medical innovation and then traces its rapid, enthusiastic adoption across European hospitals throughout European hospitals during the nineteenth century."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage follows a clear three-part structure: Semmelweis observes a disparity in mortality rates, institutes hand-washing that dramatically reduces deaths, and then faces rejection from colleagues. The option describing a historical observation followed by an intervention and surprising resistance accurately captures this progression. The option about comparing two competing theories is wrong because the passage presents only Semmelweis''s hypothesis, not a rival theory. The option about narrating a personal tragedy is wrong because the passage recounts a public health finding, not a personal loss or its emotional aftermath. The option about rapid, enthusiastic adoption directly contradicts the passage, which explicitly states that Semmelweis''s colleagues rejected his findings and widespread adoption did not occur until decades later.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DIO8KO', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the main purpose of the text?', E'Literary scholars have traditionally classified the novels of Nella Larsen as works of the Harlem Renaissance, emphasizing their treatment of racial identity in 1920s America. More recent critics, however, have drawn attention to the way Larsen''s narratives resist stable categories altogether. In "Passing," for instance, the protagonist Clare Kendry does not simply move between Black and white social worlds; she inhabits a space of radical ambiguity where identity itself becomes a performance with no authentic origin. These readings suggest that Larsen''s work anticipates poststructuralist theories of identity that would not be formally articulated until decades after her novels were published.', $lyceon_json$[{"key":"A","text":"To argue that Larsen's novels should no longer be associated with the Harlem Renaissance literary movement under any circumstances"},{"key":"B","text":"To present a shift in critical interpretation that repositions Larsen's work within a broader theoretical framework"},{"key":"C","text":"To provide a comprehensive biographical account of Nella Larsen's life and its influence on her literary output"},{"key":"D","text":"To evaluate whether poststructuralist literary theory is a valid analytical method for studying twentieth-century American fiction"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage moves from a traditional classification of Larsen''s work within the Harlem Renaissance to a newer critical reading that sees her novels as anticipating poststructuralist theories of identity. The option about presenting a shift in critical interpretation that repositions Larsen''s work within a broader theoretical framework accurately captures this purpose: the text traces an evolving scholarly conversation rather than advocating a single fixed position. The option claiming Larsen should no longer be associated with the Harlem Renaissance overstates the passage, which acknowledges the traditional classification without dismissing it entirely; the newer reading supplements rather than replaces the older one. The option about a comprehensive biographical account is wrong because the passage discusses critical interpretations of Larsen''s fiction, not her personal life. The option about evaluating poststructuralist theory is wrong because the passage uses poststructuralism as a lens to reread Larsen, not to assess the validity of the theory itself.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EIWUSB', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'The student wants to introduce the Hackensack Meadowlands to a reader unfamiliar with the site. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'While researching the ecology of urban wetlands, a student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GOHXX6', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Urban planner Fatima el-Rashidi analyzed pedestrian traffic data from nineteen intersections in Amman, Jordan, collected over a fourteen-month period. She found that intersections redesigned with curb extensions and raised crosswalks saw pedestrian volumes increase by an average of thirty-one percent, while vehicle speeds through those intersections dropped by roughly eighteen percent. Intersections that received only new paint markings without structural changes showed no statistically significant shift in either pedestrian volume or vehicle speed. El-Rashidi noted that the structural redesigns cost approximately four times as much as paint-only treatments per intersection. She argued that municipal planners evaluating pedestrian safety investments should consider that ________', $lyceon_json$[{"key":"A","text":"structural modifications to intersections produce measurable changes in both pedestrian and driver behavior, whereas cosmetic changes alone appear insufficient to alter established traffic patterns."},{"key":"B","text":"the cost of redesigning all nineteen intersections simultaneously would be prohibitive for most municipal budgets in cities comparable in size to Amman."},{"key":"C","text":"raised crosswalks are the single most important factor in reducing vehicle speeds, while curb extensions primarily affect pedestrian volume rather than driver behavior."},{"key":"D","text":"cities in the Middle East face unique pedestrian safety challenges that make the findings from Amman inapplicable to urban planning and pedestrian safety efforts in other geographic regions around the world."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that structural modifications produce measurable behavioral changes while cosmetic changes alone do not. The passage directly contrasts the outcomes of structural redesigns (increased pedestrian volume, decreased vehicle speed) with paint-only treatments (no significant change), supporting this inference. The choice about prohibitive costs introduces budget concerns the passage does not address; el-Rashidi notes cost differences but does not claim they are prohibitive. The choice isolating raised crosswalks as the single most important factor misreads the passage, which discusses curb extensions and raised crosswalks together without separating their individual effects. The choice about Middle Eastern cities facing unique challenges introduces a geographic limitation the passage never suggests.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HS5WSE', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologist Sylvia Earle has spent over seven thousand hours underwater conducting research on ocean ecosystems. Her expeditions have documented species in deep-sea habitats previously considered devoid of life. ________ Earle''s advocacy has been instrumental in establishing marine protected areas, including the designation of the Northwestern Hawaiian Islands as a national monument in 2006.', $lyceon_json$[{"key":"A","text":"Beyond her research contributions,"},{"key":"B","text":"As a result of these discoveries,"},{"key":"C","text":"Prior to this work,"},{"key":"D","text":"In contrast to her scientific achievements,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage shifts from describing Earle''s research accomplishments to discussing her policy advocacy. The transition must signal that the next sentence introduces an additional, distinct area of contribution. ''Beyond her research contributions'' correctly frames advocacy as a separate accomplishment that extends past her scientific work. ''As a result of these discoveries'' implies that the advocacy was a direct consequence of the deep-sea findings, but the passage does not establish that causal link and instead presents advocacy as a distinct sphere of influence. ''Prior to this work'' reverses the chronological logic, implying the advocacy preceded the research, which contradicts the passage''s progression. ''In contrast to her scientific achievements'' signals opposition between her research and her advocacy, but the passage presents both as complementary accomplishments, not opposing ones.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I2KX9J', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'A team of marine biologists at the University of Bergen recently cataloged the feeding behaviors of seventeen species of deep-sea amphipods collected from the Kermadec Trench in the southwestern Pacific Ocean. Contrary to previous assumptions that these organisms subsist primarily on detrital matter sinking from the surface, the researchers found that eleven of the seventeen species displayed evidence of active predation on smaller invertebrates. The study suggests that deep-sea amphipod communities possess more complex trophic interactions than earlier models indicated.', $lyceon_json$[{"key":"A","text":"Deep-sea amphipods in the Kermadec Trench possess more complex trophic interactions than researchers had previously believed."},{"key":"B","text":"Marine biologists have recently begun studying amphipod species for the first time in the southwestern Pacific Ocean region."},{"key":"C","text":"Detrital matter sinking from the ocean surface is an unreliable food source for organisms living in deep-sea trenches worldwide."},{"key":"D","text":"The Kermadec Trench harbors a greater number of amphipod species than any other deep-sea trench system that scientists have examined to date."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that deep-sea amphipods possess more complex trophic interactions than previously believed. The passage explicitly describes how eleven of seventeen species showed evidence of active predation, contradicting the prior assumption that they subsist primarily on detrital matter. The choice about biologists studying amphipods for the first time distorts the passage, which says researchers cataloged feeding behaviors, not that amphipods were being studied for the first time. The choice about detrital matter being unreliable goes beyond what the text states; the passage only says amphipods do not rely on it exclusively, not that it is unreliable. The choice about the Kermadec Trench harboring the most species introduces a comparison the passage never makes.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2J1HJ52', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which choice best describes the data in the passage that support the researchers'' conclusion?', E'Nutritional scientists at the Federal University of Minas Gerais studied iron absorption rates in adults consuming plant-based meals supplemented with different organic acids. They concluded that citric acid enhances non-heme iron absorption more effectively than malic acid when both are consumed at equivalent concentrations alongside a standardized lentil-based meal. In the study, participants who received no acid supplement absorbed an average of 4.2% of the available non-heme iron. Participants given 50 mg of malic acid absorbed 5.9%, while those given 50 mg of citric acid absorbed 8.7%. A fourth group, given 100 mg of citric acid, absorbed 11.3%.', $lyceon_json$[{"key":"A","text":"Participants who received 50 mg of citric acid absorbed 8.7% of the available iron, compared with 5.9% for participants who received the same concentration of malic acid."},{"key":"B","text":"The group receiving 100 mg of citric acid showed the highest overall absorption rate at 11.3%, demonstrating that increasing the dosage of any organic acid supplement improves iron absorption proportionally."},{"key":"C","text":"The unsupplemented group absorbed less iron (4.2%) than all three supplemented groups, indicating that organic acids in general enhance non-heme iron absorption in plant-based meals."},{"key":"D","text":"The group receiving 50 mg of malic acid absorbed more iron (5.9%) than the unsupplemented group (4.2%), confirming that malic acid is an effective standalone enhancer of non-heme iron absorption."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice comparing the 50 mg citric acid group and the 50 mg malic acid group at equal concentrations. The researchers'' conclusion is specifically that citric acid enhances iron absorption more effectively than malic acid at equivalent concentrations. The data showing 8.7% absorption with 50 mg of citric acid versus 5.9% with 50 mg of malic acid directly supports this comparative claim. The choice about the 100 mg citric acid group having the highest absorption rate introduces a claim about proportional dosage effects for any acid, which the data do not support since only citric acid was tested at two dosages. The choice about the unsupplemented group absorbing less than all supplemented groups supports a general claim about organic acids enhancing absorption, but it does not address the specific comparison between citric and malic acid that the researchers'' conclusion makes. The choice about the malic acid group versus the unsupplemented group supports malic acid''s effectiveness in isolation, which does not address the comparative claim that citric acid is more effective than malic acid.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JWQAPH', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Every autumn, the migration of monarch butterflies across the Gulf of Mexico ________ ornithologists and entomologists who gather along the Texas coastline to observe the phenomenon.', $lyceon_json$[{"key":"A","text":"astonishes"},{"key":"B","text":"astonish"},{"key":"C","text":"have astonished"},{"key":"D","text":"are astonishing to"}]$lyceon_json$::jsonb, 'A', NULL, E'The subject of the sentence is ''the migration,'' which is singular. The singular present-tense verb ''astonishes'' agrees with this singular subject. The bare form ''astonish'' fails subject-verb agreement with the singular subject. ''Have astonished'' uses a plural auxiliary that does not agree with the singular subject and shifts to present perfect tense without contextual justification. ''Are astonishing to'' uses a plural auxiliary, failing subject-verb agreement, and awkwardly restructures the predicate.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OW88SL', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'Marine biologists studying the deep-sea anglerfish have long been ______ by its bioluminescent lure, which emits a faint blue-green glow to attract prey in the perpetual darkness of the abyssal zone.', $lyceon_json$[{"key":"A","text":"fascinated"},{"key":"B","text":"horrified"},{"key":"C","text":"inconvenienced"},{"key":"D","text":"compensated"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes scientists who have studied the anglerfish''s bioluminescent lure over a long period, indicating sustained intellectual interest and wonder. "Fascinated" precisely captures this sense of deep, engaged curiosity about a remarkable natural phenomenon. "Horrified" implies fear or revulsion, which contradicts the neutral, investigative tone of the passage. "Inconvenienced" implies the lure caused practical difficulties for the biologists, which makes no sense in a research context about studying the fish. "Compensated" means repaid or rewarded, which is incoherent in the context of scientists being affected by a biological feature they observe.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PBPJXY', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'The student wants to present the somatic marker hypothesis and then note that subsequent research has supported it. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'While researching the neuroscience of decision-making, a student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PZLAQ2', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Musicologist Priya Chandrasekaran examined the compositional manuscripts of the Tamil film composer M. S. Viswanathan to understand his approach to orchestration during the 1960s and 1970s. She found that Viswanathan frequently drafted melodic lines for the veena first, then reworked them for the violin section, retaining the ornamental phrasing characteristic of Carnatic music even when the final arrangement was intended for a Western-style orchestra. Chandrasekaran observed that this practice was unusual among his contemporaries, most of whom composed directly for the instruments that would perform the final arrangement. She suggested that Viswanathan''s method accounts for a distinctive quality in his film scores: although the orchestration follows Western harmonic conventions, the melodic contours retain ________', $lyceon_json$[{"key":"A","text":"ornamental phrasing and melodic contours rooted in Carnatic idiom, giving the scores an audibly South Indian character despite their Western orchestral framework."},{"key":"B","text":"a simplicity that made them accessible to audiences unfamiliar with either Carnatic or Western classical traditions during that period of Indian cinema."},{"key":"C","text":"the exact same tonal quality they would have possessed if performed on the veena, with no perceptible difference between the drafted and final versions of each composition."},{"key":"D","text":"an improvisational character that distinguished Viswanathan's film scores from the more carefully structured compositions produced by his contemporaries working in the Tamil film industry."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice about ornamental phrasing and Carnatic melodic contours persisting within a Western orchestral framework. The passage states Viswanathan retained ornamental phrasing characteristic of Carnatic music even when writing for Western-style orchestra, and that he composed for the veena first. This logically implies the melodic contours carry Carnatic ornamental features into the final arrangement. The choice about simplicity and accessibility contradicts the passage''s emphasis on ornamental, tradition-specific phrasing, which suggests complexity rather than simplicity. The choice claiming no perceptible difference between veena drafts and final versions overstates the inference; the passage says Viswanathan reworked the lines, implying adaptation, not identical reproduction. The choice about improvisational character introduces a concept the passage does not support; drafting melodies for one instrument and reworking them for another describes a deliberate compositional method, not improvisation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PZWXFC', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'Philosopher Martha Nussbaum has argued that ancient Stoic ethics, far from being coldly rationalist, contains a ______ account of human vulnerability. In her reading, the Stoics recognized that emotional attachments to others are not weaknesses to be eliminated but essential features of a flourishing life, even as they maintained that reason should guide one''s response to loss.', $lyceon_json$[{"key":"A","text":"nuanced"},{"key":"B","text":"belligerent"},{"key":"C","text":"superficial"},{"key":"D","text":"whimsical and deliberately provocative"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes Nussbaum''s interpretation of Stoic ethics as recognizing emotional attachments as essential while still maintaining the role of reason, a view that balances competing considerations with subtlety. "Nuanced" means characterized by subtle distinctions and careful qualification, which precisely captures this layered philosophical position. "Belligerent" means aggressively hostile, which is incoherent when describing a philosophical account of human vulnerability. "Superficial" means lacking depth, which directly contradicts the passage''s depiction of a complex philosophical argument that integrates emotion and reason. "Whimsical and deliberately provocative" implies playful eccentricity and intentional controversy, neither of which aligns with the passage''s portrayal of a serious scholarly reinterpretation grounded in close textual analysis.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RSTPZQ', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, which choice best describes a point of agreement and a point of disagreement between the two authors?', E'Text 1: Archaeologist Sarah Parcak has argued that satellite remote sensing should be the foundational tool for identifying buried archaeological sites in arid landscapes. By analyzing multispectral imagery, researchers can detect subtle variations in surface vegetation and soil moisture that indicate subsurface structures, allowing them to survey vast areas at a fraction of the cost and time required by traditional ground-based methods. Parcak acknowledges that remote sensing cannot replace excavation for confirming the nature of detected anomalies but maintains that it should always precede and guide fieldwork rather than merely supplement it.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RT7YY7', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The ceramicist Ingrid Solheim fires her sculptures in a wood-burning kiln she built behind her studio in rural ________ Her partner, a metalworker named Davi Torssen, operates a separate forge on the adjacent lot.', $lyceon_json$[{"key":"A","text":"Vermont,"},{"key":"B","text":"Vermont"},{"key":"C","text":"Vermont."},{"key":"D","text":"Vermont:"}]$lyceon_json$::jsonb, 'C', NULL, E'The blank separates two independent clauses with different subjects: ''The ceramicist Ingrid Solheim fires her sculptures in a wood-burning kiln she built behind her studio in rural Vermont'' and ''Her partner, a metalworker named Davi Torssen, operates a separate forge on the adjacent lot.'' A period correctly separates these two complete sentences. Using a comma alone (''Vermont,'') creates a comma splice, which incorrectly joins two independent clauses with only a comma. Omitting punctuation entirely (''Vermont'') produces a fused run-on sentence. A colon (''Vermont:'') is incorrect because the second clause does not explain, define, or provide a list of the content in the first clause; it introduces an entirely different subject and an unrelated activity.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2U5IZ28', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the following sentence in the overall structure of the text? "By the late twentieth century, researchers had mapped the fly''s entire genome, revealing that roughly 75 percent of known human disease genes have recognizable counterparts in Drosophila."', E'The fruit fly Drosophila melanogaster has been a staple of genetics laboratories since Thomas Hunt Morgan''s pioneering experiments in the 1910s. Its short generation time and easily observable mutations made it an ideal organism for studying heredity. By the late twentieth century, researchers had mapped the fly''s entire genome, revealing that roughly 75 percent of known human disease genes have recognizable counterparts in Drosophila. This genetic similarity has made the fruit fly indispensable for modeling human diseases ranging from Parkinson''s to certain cancers.', $lyceon_json$[{"key":"A","text":"It provides a specific scientific finding that supports the claim made in the final sentence."},{"key":"B","text":"It challenges a widely accepted assumption introduced earlier in the text."},{"key":"C","text":"It offers a personal anecdote to make the scientific content more relatable to general readers."},{"key":"D","text":"It introduces an unresolved controversy within the genetics research community."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence presents the concrete finding that 75 percent of known human disease genes have counterparts in Drosophila, which directly supports the final sentence''s claim that the fruit fly is indispensable for modeling human diseases. The option describing a specific scientific finding supporting the final claim accurately captures this structural role. The option about challenging a widely accepted assumption is wrong because the underlined sentence reinforces rather than opposes the passage''s argument about the fly''s utility. The option about a personal anecdote is wrong because the sentence presents empirical genomic data, not a personal story. The option about an unresolved controversy is wrong because the sentence states an established research result without indicating any dispute.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WMZ730', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In 1987, the ethnomusicologist Raul Venegas traveled to the highlands of northern ________ he documented seventeen distinct vocal traditions that had never been formally recorded by Western scholars.', $lyceon_json$[{"key":"A","text":"Peru, where"},{"key":"B","text":"Peru where"},{"key":"C","text":"Peru. Where"},{"key":"D","text":"Peru; where"}]$lyceon_json$::jsonb, 'A', NULL, E'The clause ''where he documented seventeen distinct vocal traditions that had never been formally recorded by Western scholars'' is a nonrestrictive relative clause modifying the specific location ''the highlands of northern Peru.'' A comma before ''where'' correctly sets off this nonrestrictive clause. Omitting the comma (''Peru where'') incorrectly treats the clause as restrictive, implying there are multiple northern Perus being distinguished. Using a period before ''where'' (''Peru. Where'') creates a sentence fragment beginning with a relative pronoun. A semicolon before ''where'' (''Peru; where'') is incorrect because a semicolon must join two independent clauses, and a clause beginning with the relative pronoun ''where'' is dependent.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2X5V80O', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Historian Fernanda Ortiz has argued that the traditional periodization of the Inca Empire oversimplifies its political evolution. She contends that regional governance structures varied significantly across the empire''s four suyus, or quarters, and that local elites retained substantial administrative authority even after incorporation into the Tawantinsuyu. ________ Ortiz acknowledges that the centralized road network and mit''a labor system did impose a degree of imperial uniformity, suggesting that the reality was neither purely centralized nor purely decentralized.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"At the same time,"},{"key":"C","text":"For example,"},{"key":"D","text":"In other words, then,"}]$lyceon_json$::jsonb, 'B', NULL, E'Ortiz''s argument emphasizes decentralized, varied governance, yet the sentence after the blank concedes that centralizing mechanisms like the road network and mit''a system did create some uniformity. The transition must signal that a coexisting, partially counterbalancing consideration is being introduced rather than a full reversal or additional support. ''At the same time'' conveys this nuanced concession, indicating that Ortiz holds both ideas simultaneously. ''Furthermore'' would add a supporting point in the same direction, but the next sentence introduces a qualifying concession rather than additional support for decentralization. ''For example'' would introduce a specific illustration of the preceding claim about regional variation, but the next sentence shifts to acknowledging centralizing forces rather than exemplifying regional differences. ''In other words'' would signal a restatement of the same argument, but the next sentence introduces new information about imperial uniformity that modifies rather than restates the claim about regional variation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XJDHG4', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the geochemist from the University of Reykjavik nor the two volcanologists from the Italian institute ________ able to explain the anomalous sulfur readings detected near the caldera rim last September.', $lyceon_json$[{"key":"A","text":"were"},{"key":"B","text":"was"},{"key":"C","text":"has been"},{"key":"D","text":"is being considered as"}]$lyceon_json$::jsonb, 'A', NULL, E'In a ''neither...nor'' construction, the verb agrees with the subject closest to it. The closer subject is ''the two volcanologists from the Italian institute,'' which is plural, so the plural past tense ''were'' is required. ''Was'' incorrectly uses a singular verb, agreeing with the more distant singular subject rather than the nearer plural one. ''Has been'' is singular and shifts to present perfect tense without justification, since the passage specifies ''last September.'' ''Is being considered as'' introduces a passive construction and present progressive tense that are grammatically unsuitable and fundamentally change the meaning of the sentence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XZBZ3K', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Ecologists at the University of Tromsoe hypothesized that the recent northward expansion of red fox populations into Arctic tundra regions of northern Norway is driven primarily by rising winter temperatures, which allow red foxes to survive in areas that were previously too cold for them. The researchers noted that Arctic fox populations have declined in the same regions over the past two decades.', $lyceon_json$[{"key":"A","text":"Red fox populations have expanded northward most rapidly in the years immediately following winters with the highest average temperatures recorded in those tundra regions."},{"key":"B","text":"Arctic fox populations in northern Norway have shifted their denning sites to higher elevations over the past two decades, moving away from lowland tundra areas."},{"key":"C","text":"Red foxes in temperate regions of southern Norway have not shown any significant population changes during the same twenty-year study period examined by the researchers."},{"key":"D","text":"The diet of Arctic foxes in northern Norway has become increasingly diverse over the past decade, incorporating prey species not previously part of their typical food sources."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the finding about red fox expansion correlating with the warmest winters. This directly supports the hypothesis by showing a temporal link between rising winter temperatures and northward range expansion. The finding about Arctic foxes moving to higher elevations addresses Arctic fox behavior, not the mechanism driving red fox expansion, so it does not directly support the temperature hypothesis. The finding about red foxes in southern Norway showing no population changes concerns a different geographic region and does not address conditions enabling northward expansion. The finding about Arctic fox diet diversification pertains to Arctic foxes'' feeding habits, which is tangential to the hypothesis about winter temperatures enabling red fox survival in tundra regions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Z86HJW', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'During the 1923 Great Kanto Earthquake, fires spread so rapidly through Tokyo''s wooden neighborhoods that many residents found their planned evacuation routes ______; streets they had expected to use were blocked by collapsed buildings and advancing flames, forcing desperate improvisation.', $lyceon_json$[{"key":"A","text":"funded"},{"key":"B","text":"thwarted"},{"key":"C","text":"cataloged"},{"key":"D","text":"thwarted and entirely dismantled"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage explains that planned evacuation routes were blocked by collapsed buildings and advancing flames, forcing people to improvise. "Thwarted" means frustrated or obstructed, which precisely fits the idea that planned routes were rendered unusable by obstacles. "Funded" means financially supported, which is incoherent when describing evacuation routes blocked by disaster. "Cataloged" means systematically listed or recorded, which does not convey the obstruction described in the passage. The phrase "thwarted and entirely dismantled" overstates the passage''s meaning: the routes were blocked, not physically destroyed or taken apart, and the additional clause introduces a claim unsupported by the text.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZFSN5U', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'Historian Rosalind Gentry has challenged the prevailing interpretation of the 1847 Irrigation Compact between the settlements of Arroyo Seco and Pueblo Viejo in what is now southern New Mexico. Most scholars have treated the Compact as a straightforward water-sharing agreement driven by scarcity, but Gentry argues that the document''s provisions reveal a more strategic calculus. She points to clauses that allocated surplus water rights to Arroyo Seco in exchange for Pueblo Viejo''s exclusive access to a contested trading route, suggesting the Compact functioned less as environmental cooperation and more as a diplomatic bargain in which water was the currency rather than the objective. Gentry concedes that drought conditions motivated the initial negotiations, but she maintains that the final terms reflect political leverage rather than resource management.', $lyceon_json$[{"key":"A","text":"Gentry argues that the 1847 Irrigation Compact was fundamentally a political negotiation using water rights as leverage rather than a simple resource-sharing arrangement, even though drought prompted the talks."},{"key":"B","text":"Scholars of the American Southwest have long debated whether the 1847 Irrigation Compact was primarily an economic document or a diplomatic instrument, and Gentry's recent work has settled that debate conclusively."},{"key":"C","text":"The 1847 Irrigation Compact between Arroyo Seco and Pueblo Viejo was motivated entirely by political rivalries between the two settlements rather than by any genuine concern about water availability in the region."},{"key":"D","text":"Gentry's research reveals that the provisions of the 1847 Irrigation Compact were never actually implemented, calling into question whether the agreement had any practical significance for the settlements involved."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that Gentry views the Compact as a political negotiation using water as leverage, even though drought prompted the talks. This captures both Gentry''s central argument and her concession about drought motivating initial negotiations. The choice about scholars debating and Gentry settling the debate conclusively overstates the passage; the text presents Gentry as challenging a prevailing view, not settling a long-running debate. The choice claiming the Compact was motivated entirely by political rivalries ignores Gentry''s own concession that drought conditions motivated the initial negotiations, making the claim too absolute. The choice about provisions never being implemented introduces information absent from the passage, which discusses the Compact''s purpose, not its implementation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
